CREATE TABLE public_creative_lab_radar_cancel_responses (installation_id text NOT NULL,target_request_id text NOT NULL,lease_id text NULL,cancel_idempotency_key char(64) NOT NULL,session_id uuid NOT NULL,decision text NOT NULL,target_state text NOT NULL,response_bytes bytea NOT NULL,response_sha256 char(64) NOT NULL,created_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,CHECK (decision IN ('cancelled','cancel-not-allowed','replay')),CHECK (target_state IN ('queued','owner-busy','leased','running','succeeded','blocked','failed','cancelled','expired','unknown')),PRIMARY KEY (installation_id,target_request_id,cancel_idempotency_key),CHECK (octet_length(response_bytes)<=524288));
CREATE INDEX public_creative_lab_radar_cancel_responses_target_lease_idx ON public_creative_lab_radar_cancel_responses (target_request_id,lease_id);
